    "summary": {
      "historicalContext": "Masa awal pembentukan Partai Buruh Demokrat Sosial Rusia (RSDLP), perdebatan melawan sayap reformis/ekonomis.",
      "mainProblem": "Bagaimana membangun partai yang mampu memimpin revolusi di bawah kondisi otokrasi Tsaris?",
      "mainThesis": "Kesadaran kelas sosialis tidak tumbuh secara spontan dari perjuangan ekonomi, melainkan harus dibawa ke kelas pekerja dari luar oleh revolusioner profesional.",
      "structure": "Kritik terhadap kebebasan mengkritik, peran spontanitas, hubungan agitasi politik dan revolusi, dan pentingnya koran seluruh Rusia.",
      "contentSummary": "Meletakkan dasar bagi konsepsi partai tipe Leninis."
    },
