    "id": "negara-dan-revolusi",
    "title": "Negara dan Revolusi",
    "originalTitle": null,
    "slug": "negara-dan-revolusi",
    "authorId": "v-i-lenin",
    "authorIds": [
      "v-i-lenin"
    ],
    "year": 1917,
    "category": "Artikel",
    "difficulty": "Menengah",
    "readingTime": 15,
    "themes": [
      "Penghancuran Aparat Negara",
      "Kediktatoran Proletariat",
      "Melayunya Negara"
    ],
    "concepts": [],
    "importance": "",
    "debates": "",
    "studyQuestions": [],
    "relatedWorks": [],
    "summary": {
      "historicalContext": "Ditulis menjelang Revolusi Oktober 1917 saat Lenin bersembunyi dari Pemerintah Sementara.",
      "mainProblem": "Apa sikap kaum revolusioner proletariat terhadap negara borjuis?",
      "mainThesis": "Negara adalah organ penindasan satu kelas terhadap kelas lain. Kelas pekerja tidak dapat sekadar mengambil alih mesin negara borjuis, tetapi harus menghancurkannya dan menggantinya dengan negara tipe komune.",
      "structure": "Mengembalikan ajaran Marx dan Engels tentang negara, menganalisis pengalaman Komune Paris, dan kritik terhadap kaum Kautskyis.",
      "contentSummary": "Karya terpenting Lenin tentang hakikat negara dan fase transisi menuju komunisme."
    },
