    "id": "upah-harga-dan-laba",
    "title": "Upah Harga dan Laba",
    "originalTitle": null,
    "slug": "upah-harga-dan-laba",
    "authorId": "karl-marx",
    "authorIds": [
      "karl-marx",
      "friedrich-engels"
    ],
    "year": 1865,
    "category": "Artikel",
    "difficulty": "Menengah",
    "readingTime": 15,
    "themes": [
      "Nilai",
      "Harga",
      "Laba"
    ],
    "concepts": [],
    "importance": "",
    "debates": "",
    "studyQuestions": [],
    "relatedWorks": [],
    "summary": {
      "historicalContext": "Pidato yang disampaikan Marx kepada Dewan Umum Internasional Pertama.",
      "mainProblem": "Apakah kenaikan upah akan menyebabkan kenaikan harga barang?",
      "mainThesis": "Kenaikan umum dalam tingkat upah akan mengakibatkan jatuhnya tingkat umum laba, tetapi tidak akan memengaruhi harga rata-rata komoditas.",
      "structure": "Sanggahan terhadap argumen Weston, diikuti penjelasan tentang teori nilai dan nilai lebih.",
      "contentSummary": "Menjelaskan bahwa keuntungan kapitalis berasal dari kerja yang tidak dibayar (nilai lebih) dan bahwa serikat pekerja memainkan peran penting dalam perlawanan."
    },
    "miaUrl": "https://www.marxists.org/indonesia/archive/marx-engels/1865/upah-harga-laba.html",
