    "category": "Artikel",
    "difficulty": "Mahir",
    "readingTime": 15,
    "themes": [
      "Revolusi Permanen",
      "Rusia",
      "Kombinasi Tak Berimbang"
    ],
    "concepts": [],
    "importance": "",
    "debates": "",
