    "summary": {
      "historicalContext": "Ditulis di penjara setelah kegagalan Revolusi Rusia 1905.",
      "mainProblem": "Apa karakter revolusi Rusia yang akan datang mengingat keterbelakangan negaranya?",
      "mainThesis": "Karena borjuasi Rusia terlalu lemah, revolusi demokratik (anti-feodal) hanya bisa diselesaikan oleh kelas pekerja yang berkuasa, yang tidak akan berhenti pada batasan demokratis-borjuis tetapi beralih ke tugas-tugas sosialis.",
      "structure": "Menganalisis perkembangan historis Rusia, kota dan kapital, revolusi 1789-1848-1905, prasyarat sosialisme, dan Eropa.",
      "contentSummary": "Fondasi teori Revolusi Permanen."
    },
