    "summary": {
      "historicalContext": "Ditulis dalam pengasingan, memperluas teorinya dari 1906 ke panggung dunia, melawan teori Stalin tentang \"Sosialisme di Satu Negara\".",
      "mainProblem": "Dapatkah sosialisme dibangun di negara yang terbelakang secara terisolasi?",
      "mainThesis": "Revolusi sosialis dimulai di gelanggang nasional, berkembang di arena internasional, dan diselesaikan di panggung dunia. Sosialisme di satu negara adalah kemustahilan.",
      "structure": "Polemik komprehensif terhadap pandangan birokrasi Soviet, menjelaskan hubungan antar kelas dan antar negara.",
      "contentSummary": "Generalisasi teori Revolusi Permanen ke seluruh negara-negara dunia ketiga dan kolonial."
    },
