    "summary": {
      "historicalContext": "Dokumen pendirian Internasional Keempat.",
      "mainProblem": "Bagaimana menjembatani tuntutan ekonomi sehari-hari dengan tujuan revolusi sosialis?",
      "mainThesis": "Tuntutan-tuntutan transisional, yang berangkat dari kondisi saat ini dan kesadaran saat ini dari kelas pekerja, harus diarahkan secara tak terelakkan pada satu kesimpulan akhir: penaklukan kekuasaan oleh kaum proletariat.",
      "structure": "Menganalisis krisis kepemimpinan proletariat, tuntutan minimum dan transisional, serta tugas-tugas organisasi.",
      "contentSummary": "Sebuah panduan taktis dan strategis untuk aksi sosialis di era krisis kronis kapitalisme."
    },
