    "debates": "",
    "studyQuestions": [],
    "relatedWorks": [],
    "summary": {
      "historicalContext": "Tanggapan polemik terhadap Eduard Bernstein yang ingin merevisi Marxisme dengan menghapus keharusan revolusi.",
      "mainProblem": "Apakah sosialisme dapat dicapai melalui reformasi sosial secara bertahap atau membutuhkan revolusi politik?",
      "mainThesis": "Reformasi dan revolusi bukanlah dua metode berbeda dari kemajuan historis, melainkan momen-momen berbeda dalam perkembangan masyarakat kelas. Mengganti revolusi dengan reformasi berarti menyerah pada kapitalisme.",
      "structure": "Mengkritik teori adaptasi kapitalisme Bernstein dan mempertahankan konsepsi jatuhnya kapitalisme.",
      "contentSummary": "Pembelaan brilian terhadap inti revolusioner Marxisme dari bahaya reformisme di dalam gerakan buruh."
    },
