    "summary": {
      "historicalContext": "Pidato yang disampaikan Tan Malaka di hadapan Kongres Komunis Internasional (Komintern) ke-4 di Moskow.",
      "mainProblem": "Bagaimana sikap Komintern terhadap gerakan Pan-Islamisme?",
      "mainThesis": "Pan-Islamisme di negeri-negeri jajahan pada saat itu bukanlah gerakan keagamaan yang reaksioner, melainkan gerakan pembebasan nasional melawan imperialisme yang bisa bersekutu dengan Komunis.",
      "structure": "Pidato yang lugas menjelaskan pengalaman Sarekat Islam di Indonesia.",
      "contentSummary": "Intervensi yang sangat penting yang mengubah cara pandang Komintern terhadap gerakan agama di Timur."
    },
