    "relatedWorks": [],
    "summary": {
      "historicalContext": "Ditulis di Singapura menjelang Pemberontakan PKI 1926-1927, di mana Tan Malaka mencoba memperingatkan agar tidak melakukan pemberontakan yang prematur (putsch).",
      "mainProblem": "Bagaimana meruntuhkan kekuasaan Hindia Belanda?",
      "mainThesis": "Revolusi tidak bisa dilakukan oleh segelintir pahlawan atau pemberontakan bersenjata yang terisolasi, melainkan harus didorong oleh aksi massa dari seluruh rakyat yang tertindas.",
      "structure": "Menganalisis kondisi kapitalisme global, posisi Indonesia, kelemahan putschisme, dan pentingnya kesiapan massa rakyat.",
      "contentSummary": "Buku panduan revolusi Indonesia yang pertama dan paling berpengaruh, menolak taktik teror dan pemberontakan elitis."
    },
