    "summary": {
      "historicalContext": "Ditulis dalam persembunyian di Rawajati, Jakarta, pada masa pendudukan Jepang, sebagai buku panduan cara berpikir bagi pemuda Indonesia.",
      "mainProblem": "Bagaimana membebaskan bangsa Indonesia dari cara berpikir klenik dan mistis warisan feodal?",
      "mainThesis": "Kemerdekaan fisik tidak ada artinya tanpa kemerdekaan berpikir. Bangsa Indonesia harus mengadopsi cara berpikir materialistik dan dialektik berdasarkan ilmu pengetahuan.",
      "structure": "Membahas logika mistika, logika, dialektika, dan pandangan dunia materialis.",
      "contentSummary": "Karya magnum opus Tan Malaka dalam bidang filsafat, sebuah usaha luar biasa membumikan Marxisme ke dalam konteks kebudayaan Nusantara."
    },
